EXTRAS = {'build_extra': {'en': 'All six firmware components (three bootloaders and three applications, one pair per chip or core) have their own version. Building never changes it: `build_firmware.sh` and `.bat` only report it. Raising versions is the explicit `python bump_firmware_versions.py` (`--list` shows them), and `python show_component_version.py` prints the version a component has.', 'es': 'Los seis componentes del firmware (tres cargadores de arranque y tres aplicaciones, un par por chip o núcleo) tienen cada uno su versión. Compilar nunca la cambia: `build_firmware.sh` y `.bat` solo la informan. Subir versiones es el comando explícito `python bump_firmware_versions.py` (`--list` las muestra), y `python show_component_version.py` imprime la versión de un componente.', 'de': 'Alle sechs Firmware-Komponenten (drei Bootloader und drei Anwendungen, ein Paar je Chip oder Kern) haben ihre eigene Version. Das Bauen ändert sie nie: `build_firmware.sh` und `.bat` melden sie nur. Versionen erhöht der ausdrückliche Befehl `python bump_firmware_versions.py` (`--list` zeigt sie), und `python show_component_version.py` gibt die Version einer Komponente aus.', 'fr': "Les six composants du firmware (trois chargeurs d'amorçage et trois applications, une paire par puce ou cœur) ont chacun leur version. Compiler ne la change jamais : `build_firmware.sh` et `.bat` ne font que la signaler. Monter les versions est la commande explicite `python bump_firmware_versions.py` (`--list` les montre), et `python show_component_version.py` affiche la version d'un composant.", 'it': 'Tutti e sei i componenti del firmware (tre bootloader e tre applicazioni, una coppia per chip o core) hanno la propria versione. Compilare non la cambia mai: `build_firmware.sh` e `.bat` si limitano a riportarla. Alzare le versioni è il comando esplicito `python bump_firmware_versions.py` (`--list` le mostra), e `python show_component_version.py` stampa la versione di un componente.', 'ja': '6 つのファームウェアコンポーネント（チップまたはコアごとにブートローダーとアプリケーションの組）にはそれぞれ独自のバージョンがあります。ビルドでは変わらず、`build_firmware.sh` と `.bat` は報告するだけです。バージョンを上げるのは明示的なコマンド `python bump_firmware_versions.py`（`--list` で一覧）で、`python show_component_version.py` はコンポーネントのバージョンを表示します。', 'zh': '六个固件组件（每个芯片或内核一对引导程序和应用）各有自己的版本。构建从不改变它：`build_firmware.sh` 和 `.bat` 只报告版本。提升版本要使用明确的命令 `python bump_firmware_versions.py`（`--list` 列出它们），`python show_component_version.py` 会打印某个组件的版本。', 'pt': 'Os seis componentes do firmware (três carregadores de arranque e três aplicações, um par por chip ou núcleo) têm cada um a sua versão. Compilar nunca a altera: `build_firmware.sh` e `.bat` só a comunicam. Subir versões é o comando explícito `python bump_firmware_versions.py` (`--list` mostra-as), e `python show_component_version.py` imprime a versão de um componente.'}, 'security': {'rows': [[{'en': 'A forged or edited firmware image', 'es': 'Una imagen de firmware falsa o editada', 'de': 'Ein gefälschtes oder bearbeitetes Firmware-Image', 'fr': 'Une image de firmware falsifiée ou modifiée', 'it': "Un'immagine firmware falsa o modificata", 'ja': '偽造または編集されたファームウェアイメージ', 'zh': '伪造或被篡改的固件镜像', 'pt': 'Uma imagem de firmware falsa ou editada'}, {'en': 'A fixed 64-byte header (magic, version, hardware id, size, vector words, CRC-32) is followed by the image and a 64-byte Ed25519 signature over header and image; the bootloader checks the signature first and believes nothing in the header before it verifies', 'es': 'Una cabecera fija de 64 bytes (magia, versión, id de hardware, tamaño, palabras de vector, CRC-32) va seguida de la imagen y de una firma Ed25519 de 64 bytes sobre cabecera e imagen; el cargador comprueba primero la firma y no cree nada de la cabecera antes de que verifique', 'de': 'Auf einen festen 64-Byte-Header (Magic, Version, Hardware-ID, Größe, Vektorwörter, CRC-32) folgen das Image und eine 64-Byte-Ed25519-Signatur über Header und Image; der Bootloader prüft zuerst die Signatur und glaubt nichts im Header, bevor sie verifiziert', 'fr': "Un en-tête fixe de 64 octets (magic, version, id matériel, taille, mots de vecteur, CRC-32) est suivi de l'image et d'une signature Ed25519 de 64 octets sur l'en-tête et l'image ; le chargeur vérifie d'abord la signature et ne croit rien de l'en-tête avant qu'elle soit vérifiée", 'it': "Un'intestazione fissa di 64 byte (magic, versione, id hardware, dimensione, parole di vettore, CRC-32) è seguita dall'immagine e da una firma Ed25519 di 64 byte su intestazione e immagine; il bootloader controlla prima la firma e non crede a nulla dell'intestazione prima che sia verificata", 'ja': '固定の 64 バイトのヘッダー（マジック、バージョン、ハードウェア ID、サイズ、ベクターワード、CRC-32）にイメージと、ヘッダーとイメージにかけた 64 バイトの Ed25519 署名が続きます。ブートローダーはまず署名を確認し、検証が通るまでヘッダーの内容を一切信用しません', 'zh': '固定的 64 字节头部（魔数、版本、硬件 ID、大小、向量字、CRC-32）之后是镜像和对头部与镜像的 64 字节 Ed25519 签名；引导程序先验签，验证通过之前不相信头部的任何内容', 'pt': 'Um cabeçalho fixo de 64 bytes (magia, versão, id de hardware, tamanho, palavras de vetor, CRC-32) é seguido da imagem e de uma assinatura Ed25519 de 64 bytes sobre cabeçalho e imagem; o carregador verifica primeiro a assinatura e não acredita em nada do cabeçalho antes de ela verificar'}, '`image_header.h`, `tools/image_header.py`'], [{'en': 'An old signed image sent again (rollback)', 'es': 'Una imagen firmada antigua enviada de nuevo (retroceso)', 'de': 'Ein altes signiertes Image, das erneut gesendet wird (Rollback)', 'fr': 'Une ancienne image signée renvoyée (retour en arrière)', 'it': 'Una vecchia immagine firmata inviata di nuovo (rollback)', 'ja': '古い署名付きイメージの再送（ロールバック）', 'zh': '重新发送的旧签名镜像（回滚）', 'pt': 'Uma imagem assinada antiga enviada de novo (retrocesso)'}, {'en': 'A new image must be strictly newer than the installed one (major, minor and patch are compared); an older one is accepted only with a downgrade token, an Ed25519 signature over the installed and target versions and the image digest; the firmware holds no constant that allows a downgrade', 'es': 'Una imagen nueva debe ser estrictamente más nueva que la instalada (se comparan mayor, menor y parche); una más antigua solo se acepta con un token de bajada de versión, una firma Ed25519 sobre las versiones instalada y destino y el resumen de la imagen; el firmware no contiene ninguna constante que permita bajar de versión', 'de': 'Ein neues Image muss strikt neuer sein als das installierte (Major, Minor und Patch werden verglichen); ein älteres wird nur mit einem Downgrade-Token akzeptiert, einer Ed25519-Signatur über installierte und Zielversion und den Image-Digest; die Firmware enthält keine Konstante, die ein Downgrade erlaubt', 'fr': "Une nouvelle image doit être strictement plus récente que celle installée (majeure, mineure et correctif sont comparés) ; une plus ancienne n'est acceptée qu'avec un jeton de rétrogradation, une signature Ed25519 sur les versions installée et cible et le condensat de l'image ; le firmware ne contient aucune constante permettant de rétrograder", 'it': "Una nuova immagine deve essere strettamente più recente di quella installata (si confrontano maggiore, minore e patch); una più vecchia è accettata solo con un token di downgrade, una firma Ed25519 sulle versioni installata e di destinazione e sul digest dell'immagine; il firmware non contiene alcuna costante che consenta un downgrade", 'ja': '新しいイメージはインストール済みのものより厳密に新しくなければなりません（メジャー・マイナー・パッチを比較）。古いイメージは、インストール済みと対象のバージョンおよびイメージのダイジェストにかけた Ed25519 署名であるダウングレードトークンがある場合にだけ受け入れられ、ファームウェアにはダウングレードを許す定数はありません', 'zh': '新镜像必须严格比已安装的更新（比较主版本、次版本和补丁号）；更旧的镜像只有在带有降级令牌时才被接受，该令牌是对已安装版本、目标版本和镜像摘要的 Ed25519 签名；固件中没有任何允许降级的常量', 'pt': 'Uma imagem nova tem de ser estritamente mais nova do que a instalada (comparam-se maior, menor e correção); uma mais antiga só é aceite com um token de descida de versão, uma assinatura Ed25519 sobre as versões instalada e de destino e o resumo da imagem; o firmware não contém nenhuma constante que permita descer de versão'}, '`image_header.h`, `ImageHeader_CheckRollback`'], [{'en': 'Images built with the development keys', 'es': 'Imágenes compiladas con las claves de desarrollo', 'de': 'Mit den Entwicklungsschlüsseln gebaute Images', 'fr': 'Des images compilées avec les clés de développement', 'it': 'Immagini compilate con le chiavi di sviluppo', 'ja': '開発用の鍵でビルドされたイメージ', 'zh': '用开发密钥构建的镜像', 'pt': 'Imagens compiladas com as chaves de desenvolvimento'}, {'en': 'Without `HYDRA_FW_UPDATE_PUBKEY_HEX` and `HYDRA_FW_HMAC_KEY_HEX` the bootloaders carry development keys whose private part is published in the repository; the build warns, and with `HYDRA_UMC_RELEASE=1` it refuses to build; the board holds only the public key, the private seed stays with the owner', 'es': 'Sin `HYDRA_FW_UPDATE_PUBKEY_HEX` y `HYDRA_FW_HMAC_KEY_HEX` los cargadores llevan claves de desarrollo cuya parte privada está publicada en el repositorio; la compilación avisa, y con `HYDRA_UMC_RELEASE=1` se niega a compilar; la placa solo guarda la clave pública, la semilla privada queda con el dueño', 'de': 'Ohne `HYDRA_FW_UPDATE_PUBKEY_HEX` und `HYDRA_FW_HMAC_KEY_HEX` tragen die Bootloader Entwicklungsschlüssel, deren privater Teil im Repository veröffentlicht ist; der Build warnt, und mit `HYDRA_UMC_RELEASE=1` weigert er sich zu bauen; die Platine hält nur den öffentlichen Schlüssel, der private Seed bleibt beim Eigentümer', 'fr': 'Sans `HYDRA_FW_UPDATE_PUBKEY_HEX` et `HYDRA_FW_HMAC_KEY_HEX`, les chargeurs portent des clés de développement dont la partie privée est publiée dans le dépôt ; la compilation avertit, et avec `HYDRA_UMC_RELEASE=1` elle refuse de compiler ; la carte ne détient que la clé publique, la graine privée reste chez le propriétaire', 'it': 'Senza `HYDRA_FW_UPDATE_PUBKEY_HEX` e `HYDRA_FW_HMAC_KEY_HEX` i bootloader portano chiavi di sviluppo la cui parte privata è pubblicata nel repository; la compilazione avvisa, e con `HYDRA_UMC_RELEASE=1` si rifiuta di compilare; la scheda tiene solo la chiave pubblica, il seme privato resta al proprietario', 'ja': '`HYDRA_FW_UPDATE_PUBKEY_HEX` と `HYDRA_FW_HMAC_KEY_HEX` がないと、ブートローダーには秘密部分がリポジトリで公開されている開発用の鍵が入ります。ビルドは警告し、`HYDRA_UMC_RELEASE=1` ではビルドを拒否します。基板が持つのは公開鍵だけで、秘密のシードは所有者の手元に残ります', 'zh': '没有 `HYDRA_FW_UPDATE_PUBKEY_HEX` 和 `HYDRA_FW_HMAC_KEY_HEX` 时，引导程序带有私有部分已公布在仓库中的开发密钥；构建会发出警告，设置 `HYDRA_UMC_RELEASE=1` 时会拒绝构建；电路板只持有公钥，私钥种子由所有者保管', 'pt': 'Sem `HYDRA_FW_UPDATE_PUBKEY_HEX` e `HYDRA_FW_HMAC_KEY_HEX` os carregadores levam chaves de desenvolvimento cuja parte privada está publicada no repositório; a compilação avisa, e com `HYDRA_UMC_RELEASE=1` recusa-se a compilar; a placa guarda só a chave pública, a semente privada fica com o dono'}, '`build_firmware.sh`'], [{'en': 'A board that hangs', 'es': 'Una placa que se cuelga', 'de': 'Eine Platine, die hängt', 'fr': 'Une carte qui se bloque', 'it': 'Una scheda che si blocca', 'ja': 'ハングする基板', 'zh': '死机的电路板', 'pt': 'Uma placa que fica presa'}, {'en': 'The G474 bootloader arms the independent watchdog (IWDG) as the very first action of `main()`, before `HAL_Init()`, so a hang during start-up resets the chip', 'es': 'El cargador de la G474 arma el perro guardián independiente (IWDG) como primerísima acción de `main()`, antes de `HAL_Init()`, así que un cuelgue durante el arranque reinicia el chip', 'de': 'Der G474-Bootloader schärft den unabhängigen Watchdog (IWDG) als allererste Aktion von `main()`, vor `HAL_Init()`, sodass ein Hänger beim Start den Chip zurücksetzt', 'fr': "Le chargeur G474 arme le chien de garde indépendant (IWDG) comme toute première action de `main()`, avant `HAL_Init()`, si bien qu'un blocage au démarrage réinitialise la puce", 'it': "Il bootloader della G474 arma il watchdog indipendente (IWDG) come primissima azione di `main()`, prima di `HAL_Init()`, così un blocco all'avvio reimposta il chip", 'ja': 'G474 のブートローダーは `main()` の最初の処理として、`HAL_Init()` より前に独立ウォッチドッグ（IWDG）を有効にするため、起動中のハングはチップをリセットします', 'zh': 'G474 引导程序在 `main()` 的第一个动作中、早于 `HAL_Init()` 启用独立看门狗（IWDG），因此启动期间的挂起会使芯片复位', 'pt': 'O carregador da G474 arma o cão de guarda independente (IWDG) como primeiríssima ação de `main()`, antes de `HAL_Init()`, pelo que um bloqueio no arranque reinicia o chip'}, '`src/mcu_stm32g474/boot/bootloader_main.c`'], [{'en': 'The local HTTP service of the SPI bridge reached by someone else', 'es': 'El servicio HTTP local del puente SPI alcanzado por otra persona', 'de': 'Der lokale HTTP-Dienst der SPI-Brücke wird von jemand anderem erreicht', 'fr': "Le service HTTP local du pont SPI atteint par quelqu'un d'autre", 'it': 'Il servizio HTTP locale del bridge SPI raggiunto da qualcun altro', 'ja': 'SPI ブリッジのローカル HTTP サービスに他者が到達する', 'zh': 'SPI 桥的本地 HTTP 服务被他人访问', 'pt': 'O serviço HTTP local da ponte SPI alcançado por outra pessoa'}, {'en': 'It listens on 127.0.0.1 by default, accepts a firmware body of at most 4 MiB, and holds no signing key: the signature comes in the request, made on the machine that holds the private seed; it has no TLS and no sign-in of its own, so whatever relays to it must decide who may flash', 'es': 'Escucha en 127.0.0.1 por defecto, acepta un cuerpo de firmware de 4 MiB como máximo y no guarda ninguna clave de firma: la firma llega en la petición, hecha en la máquina que tiene la semilla privada; no tiene TLS ni inicio de sesión propio, así que quien le reenvíe debe decidir quién puede flashear', 'de': 'Er lauscht standardmäßig auf 127.0.0.1, nimmt einen Firmware-Body von höchstens 4 MiB an und hält keinen Signierschlüssel: Die Signatur kommt in der Anfrage, erstellt auf dem Rechner mit dem privaten Seed; er hat weder TLS noch eigene Anmeldung, wer an ihn weiterleitet, muss also entscheiden, wer flashen darf', 'fr': "Il écoute sur 127.0.0.1 par défaut, accepte un corps de firmware de 4 Mio au plus et ne détient aucune clé de signature : la signature arrive dans la requête, faite sur la machine qui détient la graine privée ; il n'a ni TLS ni connexion propre, donc ce qui lui relaie doit décider qui peut flasher", 'it': 'Ascolta su 127.0.0.1 per impostazione predefinita, accetta un corpo di firmware di al massimo 4 MiB e non conserva alcuna chiave di firma: la firma arriva nella richiesta, fatta sulla macchina che ha il seme privato; non ha TLS né un accesso proprio, quindi chi gli inoltra le richieste deve decidere chi può flashare', 'ja': '既定では 127.0.0.1 で待ち受け、ファームウェア本体は最大 4 MiB まで受け付け、署名鍵は持ちません。署名は秘密のシードを持つマシンで作られてリクエストに含まれます。TLS も独自のサインインもないため、中継する側が誰がフラッシュできるかを決める必要があります', 'zh': '默认监听 127.0.0.1，接受的固件正文最大为 4 MiB，且不持有签名密钥：签名随请求而来，由持有私钥种子的机器生成；它没有 TLS，也没有自己的登录，因此向它转发请求的一方必须决定谁可以刷写', 'pt': 'Escuta em 127.0.0.1 por predefinição, aceita um corpo de firmware de 4 MiB no máximo e não guarda nenhuma chave de assinatura: a assinatura chega no pedido, feita na máquina que tem a semente privada; não tem TLS nem início de sessão próprio, pelo que quem lhe reencaminha pedidos deve decidir quem pode gravar'}, '`src/cm5_host/spi_bridge/spi_bridge/http_service.py`']], 'never': {'en': '**What it never does today:** provide an emergency stop, software limits, interlocks, the power-loss dump to FRAM or any motion command; Secure Boot and read-out protection of the flash are not claimed. Read the safety box at the top before relying on anything here.', 'es': '**Lo que hoy nunca hace:** dar una parada de emergencia, límites por software, enclavamientos, el volcado a FRAM al perder la alimentación ni ninguna orden de movimiento; no se afirma Secure Boot ni protección de lectura de la flash. Lee el recuadro de seguridad de arriba antes de fiarte de algo de aquí.', 'de': '**Was es heute nie tut:** einen Not-Halt, Software-Grenzen, Verriegelungen, den Sicherungsabzug in den FRAM bei Spannungsverlust oder irgendeinen Bewegungsbefehl bereitstellen; Secure Boot und Ausleseschutz des Flashs werden nicht behauptet. Lies den Sicherheitskasten oben, bevor du dich auf etwas hier verlässt.', 'fr': "**Ce qu'il ne fait jamais aujourd'hui :** fournir un arrêt d'urgence, des limites logicielles, des verrouillages, la sauvegarde vers la FRAM en cas de coupure ni aucune commande de mouvement ; Secure Boot et la protection en lecture de la flash ne sont pas revendiqués. Lisez l'encadré de sécurité en haut avant de vous fier à quoi que ce soit ici.", 'it': '**Cosa non fa mai oggi:** fornire un arresto di emergenza, limiti software, interblocchi, il salvataggio su FRAM alla perdita di alimentazione né alcun comando di movimento; Secure Boot e protezione in lettura della flash non sono dichiarati. Leggi il riquadro di sicurezza in alto prima di fidarti di qualsiasi cosa qui.', 'ja': '**現時点で絶対にしないこと：** 非常停止、ソフトウェア制限、インターロック、電源喪失時の FRAM へのダンプ、あらゆる動作コマンドの提供。Secure Boot とフラッシュの読み出し保護は主張していません。ここにあるものを頼りにする前に、冒頭の安全に関する注意を読んでください。', 'zh': '**目前绝不做的事：** 提供紧急停止、软件限位、联锁、掉电时转储到 FRAM 或任何运动命令；不声称具备 Secure Boot 和闪存读出保护。依赖这里的任何内容之前，请先阅读顶部的安全说明框。', 'pt': '**O que hoje nunca faz:** dar uma paragem de emergência, limites por software, bloqueios, o despejo para a FRAM na perda de alimentação nem qualquer comando de movimento; não se afirma Secure Boot nem proteção de leitura da flash. Leia a caixa de segurança no topo antes de confiar em algo daqui.'}}, 'interfaces': {'head': 'topic', 'rows': [['CAN, FDCAN1 in classic mode', {'en': 'one bus (STACK A) from the STM32H745 to up to eight Robot Controller Boards; the identifiers of the relay protocol are listed once in `tools/can_ids.py` and checked by `tests/test_can_ids.py`', 'es': 'un bus (STACK A) del STM32H745 a hasta ocho Robot Controller Boards; los identificadores del protocolo de relé están en una sola tabla, `tools/can_ids.py`, y los comprueba `tests/test_can_ids.py`', 'de': 'ein Bus (STACK A) vom STM32H745 zu bis zu acht Robot Controller Boards; die Kennungen des Relay-Protokolls stehen einmal in `tools/can_ids.py` und werden von `tests/test_can_ids.py` geprüft', 'fr': "un bus (STACK A) du STM32H745 à jusqu'à huit Robot Controller Boards ; les identifiants du protocole de relais sont listés une seule fois dans `tools/can_ids.py` et vérifiés par `tests/test_can_ids.py`", 'it': "un bus (STACK A) dall'STM32H745 fino a otto Robot Controller Board; gli identificatori del protocollo relay sono elencati una sola volta in `tools/can_ids.py` e controllati da `tests/test_can_ids.py`", 'ja': 'STM32H745 から最大 8 枚の Robot Controller Board へ至る 1 本のバス（STACK A）。リレープロトコルの識別子は `tools/can_ids.py` に 1 度だけ列挙され、`tests/test_can_ids.py` が検査します', 'zh': '从 STM32H745 到最多八块 Robot Controller Board 的一条总线（STACK A）；中继协议的标识符只在 `tools/can_ids.py` 中列出一次，由 `tests/test_can_ids.py` 检查', 'pt': 'um bus (STACK A) do STM32H745 até oito Robot Controller Boards; os identificadores do protocolo de relé estão listados uma só vez em `tools/can_ids.py` e verificados por `tests/test_can_ids.py`'}], ['SPI + DMA + IRQ pin, 128-byte frames', {'en': 'the CM5 to the STM32H745: fixed `SpiOtaFrame` frames that match the C struct byte for byte; the bridge runs at 10 MHz by default', 'es': 'de la CM5 al STM32H745: tramas fijas `SpiOtaFrame` que coinciden con la estructura de C byte a byte; el puente funciona a 10 MHz por defecto', 'de': 'von der CM5 zum STM32H745: feste `SpiOtaFrame`-Frames, die der C-Struktur Byte für Byte entsprechen; die Brücke läuft standardmäßig mit 10 MHz', 'fr': 'de la CM5 au STM32H745 : trames fixes `SpiOtaFrame` qui correspondent à la structure C octet par octet ; le pont tourne à 10 MHz par défaut', 'it': "dalla CM5 all'STM32H745: frame fissi `SpiOtaFrame` che corrispondono alla struct C byte per byte; il bridge gira a 10 MHz per impostazione predefinita", 'ja': 'CM5 から STM32H745 へ：C 構造体とバイト単位で一致する固定の `SpiOtaFrame` フレーム。ブリッジは既定で 10 MHz で動作します', 'zh': '从 CM5 到 STM32H745：与 C 结构体逐字节一致的固定 `SpiOtaFrame` 帧；桥默认运行在 10 MHz', 'pt': 'da CM5 ao STM32H745: tramas fixas `SpiOtaFrame` que coincidem byte a byte com a estrutura em C; a ponte corre a 10 MHz por predefinição'}], ['`GET /version`, `GET /counters`, `POST /flash` on 127.0.0.1:8765', {'en': "the local service of the SPI bridge: a board's version, the error counters of its CAN controller, and a streamed flash (newline-delimited JSON) of an image with its Ed25519 signature; `relay=1` reaches a URTC tool head through its Robot Controller Board", 'es': 'el servicio local del puente SPI: la versión de una placa, los contadores de error de su controlador CAN y un flasheo con respuesta en flujo (JSON delimitado por líneas) de una imagen con su firma Ed25519; `relay=1` llega a una cabeza URTC a través de su Robot Controller Board', 'de': 'der lokale Dienst der SPI-Brücke: die Version einer Platine, die Fehlerzähler ihres CAN-Controllers und ein Flash als Strom (zeilengetrenntes JSON) eines Images mit seiner Ed25519-Signatur; `relay=1` erreicht einen URTC-Werkzeugkopf über sein Robot Controller Board', 'fr': "le service local du pont SPI : la version d'une carte, les compteurs d'erreurs de son contrôleur CAN et un flash en flux (JSON délimité par lignes) d'une image avec sa signature Ed25519 ; `relay=1` atteint une tête d'outil URTC via sa Robot Controller Board", 'it': "il servizio locale del bridge SPI: la versione di una scheda, i contatori di errore del suo controller CAN e un flash in streaming (JSON delimitato da righe) di un'immagine con la sua firma Ed25519; `relay=1` raggiunge una testa utensile URTC attraverso la sua Robot Controller Board", 'ja': 'SPI ブリッジのローカルサービス：基板のバージョン、その CAN コントローラーのエラーカウンター、Ed25519 署名付きイメージのストリーミング書き込み（改行区切り JSON）。`relay=1` で Robot Controller Board 経由の URTC ツールヘッドに到達します', 'zh': 'SPI 桥的本地服务：电路板的版本、其 CAN 控制器的错误计数器，以及带 Ed25519 签名的镜像的流式刷写（按行分隔的 JSON）；`relay=1` 通过 Robot Controller Board 到达 URTC 工具头', 'pt': 'o serviço local da ponte SPI: a versão de uma placa, os contadores de erro do seu controlador CAN e uma gravação em fluxo (JSON delimitado por linhas) de uma imagem com a sua assinatura Ed25519; `relay=1` chega a uma cabeça URTC através da sua Robot Controller Board'}], ['`tools/image_header.py sign | keygen | pubkey`', {'en': 'the host reference of the signed image header: it makes the signatures and downgrade tokens that the bootloaders check, and `tests/image_header_vectors.h` is generated from it so that the C and Python sides cannot drift', 'es': 'la referencia en el anfitrión de la cabecera de imagen firmada: hace las firmas y los tokens de bajada de versión que comprueban los cargadores, y de ella se genera `tests/image_header_vectors.h` para que los lados C y Python no se separen', 'de': 'die Host-Referenz des signierten Image-Headers: Sie erzeugt die Signaturen und Downgrade-Token, die die Bootloader prüfen, und `tests/image_header_vectors.h` wird daraus erzeugt, damit C- und Python-Seite nicht auseinanderlaufen', 'fr': "la référence côté hôte de l'en-tête d'image signé : elle fait les signatures et les jetons de rétrogradation que les chargeurs vérifient, et `tests/image_header_vectors.h` en est généré pour que les côtés C et Python ne divergent pas", 'it': "il riferimento sull'host dell'intestazione immagine firmata: produce le firme e i token di downgrade che i bootloader controllano, e `tests/image_header_vectors.h` è generato da esso perché i lati C e Python non divergano", 'ja': '署名付きイメージヘッダーのホスト側リファレンス：ブートローダーが検査する署名とダウングレードトークンを作り、C 側と Python 側がずれないよう `tests/image_header_vectors.h` はそこから生成されます', 'zh': '签名镜像头的主机参考实现：它生成引导程序所检查的签名和降级令牌，`tests/image_header_vectors.h` 由它生成，使 C 和 Python 两侧不会漂移', 'pt': 'a referência no anfitrião do cabeçalho de imagem assinado: faz as assinaturas e os tokens de descida de versão que os carregadores verificam, e `tests/image_header_vectors.h` é gerado a partir dela para que os lados C e Python não se afastem'}]]}, 'configuration': {'intro': {'en': 'The firmware is configured when it is built, through environment variables; the SPI bridge takes its settings from its command line.', 'es': 'El firmware se configura al compilarse, mediante variables de entorno; el puente SPI toma sus ajustes de su línea de órdenes.', 'de': 'Die Firmware wird beim Bauen über Umgebungsvariablen konfiguriert; die SPI-Brücke nimmt ihre Einstellungen von der Befehlszeile.', 'fr': "Le firmware se configure à la compilation, par des variables d'environnement ; le pont SPI prend ses réglages sur sa ligne de commande.", 'it': "Il firmware si configura al momento della compilazione, tramite variabili d'ambiente; il bridge SPI prende le sue impostazioni dalla riga di comando.", 'ja': 'ファームウェアはビルド時に環境変数で設定します。SPI ブリッジの設定はコマンドラインから取ります。', 'zh': '固件在构建时通过环境变量配置；SPI 桥的设置来自其命令行。', 'pt': 'O firmware configura-se ao compilar, através de variáveis de ambiente; a ponte SPI recebe as suas definições da linha de comandos.'}, 'rows': [['`HYDRA_FW_UPDATE_PUBKEY_HEX`', {'en': 'development key', 'es': 'clave de desarrollo', 'de': 'Entwicklungsschlüssel', 'fr': 'clé de développement', 'it': 'chiave di sviluppo', 'ja': '開発用の鍵', 'zh': '开发密钥', 'pt': 'chave de desenvolvimento'}, {'en': '64 hexadecimal digits: the Ed25519 public key that an update must be signed for', 'es': '64 dígitos hexadecimales: la clave pública Ed25519 para la que debe estar firmada una actualización', 'de': '64 Hexadezimalziffern: der öffentliche Ed25519-Schlüssel, für den ein Update signiert sein muss', 'fr': '64 chiffres hexadécimaux : la clé publique Ed25519 pour laquelle une mise à jour doit être signée', 'it': '64 cifre esadecimali: la chiave pubblica Ed25519 per cui deve essere firmato un aggiornamento', 'ja': '64 桁の 16 進数：更新が署名されていなければならない Ed25519 公開鍵', 'zh': '64 位十六进制数字：更新必须为其签名的 Ed25519 公钥', 'pt': '64 dígitos hexadecimais: a chave pública Ed25519 para a qual uma atualização tem de estar assinada'}], ['`HYDRA_FW_HMAC_KEY_HEX`', {'en': 'development key', 'es': 'clave de desarrollo', 'de': 'Entwicklungsschlüssel', 'fr': 'clé de développement', 'it': 'chiave di sviluppo', 'ja': '開発用の鍵', 'zh': '开发密钥', 'pt': 'chave de desenvolvimento'}, {'en': '64 hexadecimal digits kept outside the repository: the key of the local integrity check of the installed application', 'es': '64 dígitos hexadecimales guardados fuera del repositorio: la clave de la comprobación de integridad local de la aplicación instalada', 'de': '64 Hexadezimalziffern außerhalb des Repositorys: der Schlüssel der lokalen Integritätsprüfung der installierten Anwendung', 'fr': "64 chiffres hexadécimaux gardés hors du dépôt : la clé du contrôle d'intégrité local de l'application installée", 'it': "64 cifre esadecimali tenute fuori dal repository: la chiave del controllo di integrità locale dell'applicazione installata", 'ja': 'リポジトリの外に保管する 64 桁の 16 進数：インストール済みアプリケーションのローカル整合性検査の鍵', 'zh': '保存在仓库之外的 64 位十六进制数字：已安装应用的本地完整性检查的密钥', 'pt': '64 dígitos hexadecimais guardados fora do repositório: a chave da verificação de integridade local da aplicação instalada'}], ['`HYDRA_UMC_RELEASE`', '`0`', {'en': 'with `1` the build refuses to use the development keys', 'es': 'con `1` la compilación se niega a usar las claves de desarrollo', 'de': 'mit `1` weigert sich der Build, die Entwicklungsschlüssel zu verwenden', 'fr': "avec `1` la compilation refuse d'utiliser les clés de développement", 'it': 'con `1` la compilazione si rifiuta di usare le chiavi di sviluppo', 'ja': '`1` にするとビルドは開発用の鍵の使用を拒否します', 'zh': '设为 `1` 时，构建拒绝使用开发密钥', 'pt': 'com `1` a compilação recusa-se a usar as chaves de desenvolvimento'}], ['`HYDRA_UMC_SKIP_HOST_TESTS`, `HOST_CC`', {'en': '`0`, the system compiler', 'es': '`0`, el compilador del sistema', 'de': '`0`, der System-Compiler', 'fr': '`0`, le compilateur du système', 'it': '`0`, il compilatore di sistema', 'ja': '`0`、システムのコンパイラー', 'zh': '`0`，系统编译器', 'pt': '`0`, o compilador do sistema'}, {'en': 'skip the host logic tests of step 1b, or name the C compiler they use', 'es': 'omite las pruebas lógicas de host del paso 1b, o nombra el compilador de C que usan', 'de': 'überspringt die Host-Logiktests von Schritt 1b oder benennt den C-Compiler, den sie verwenden', 'fr': "saute les tests logiques hôte de l'étape 1b, ou nomme le compilateur C qu'ils utilisent", 'it': 'salta i test logici host del passo 1b, o indica il compilatore C che usano', 'ja': 'ステップ 1b のホストロジックテストを省略するか、それが使う C コンパイラーを指定します', 'zh': '跳过 1b 步骤的主机逻辑测试，或指定它们所用的 C 编译器', 'pt': 'salta os testes lógicos de anfitrião do passo 1b, ou indica o compilador de C que usam'}], ['`python -m spi_bridge run --spi-speed-hz --host --port --collector-url`', '`10000000`, `127.0.0.1`, `8765`', {'en': 'the SPI clock, where the local HTTP service listens, and the address of the HYDRA-UMC-TELEMETRY-COLLECTOR that the bridge can report to (at most one report a second)', 'es': 'el reloj SPI, dónde escucha el servicio HTTP local y la dirección del HYDRA-UMC-TELEMETRY-COLLECTOR al que el puente puede informar (como mucho un informe por segundo)', 'de': 'der SPI-Takt, wo der lokale HTTP-Dienst lauscht, und die Adresse des HYDRA-UMC-TELEMETRY-COLLECTOR, an den die Brücke berichten kann (höchstens ein Bericht pro Sekunde)', 'fr': "l'horloge SPI, où écoute le service HTTP local et l'adresse du HYDRA-UMC-TELEMETRY-COLLECTOR auquel le pont peut rendre compte (au plus un rapport par seconde)", 'it': "il clock SPI, dove ascolta il servizio HTTP locale e l'indirizzo dell'HYDRA-UMC-TELEMETRY-COLLECTOR a cui il bridge può riferire (al massimo un rapporto al secondo)", 'ja': 'SPI クロック、ローカル HTTP サービスの待ち受け先、ブリッジが報告できる HYDRA-UMC-TELEMETRY-COLLECTOR のアドレス（報告は 1 秒に 1 回まで）', 'zh': 'SPI 时钟、本地 HTTP 服务的监听位置，以及桥可以向其报告的 HYDRA-UMC-TELEMETRY-COLLECTOR 的地址（每秒最多一次报告）', 'pt': 'o relógio SPI, onde escuta o serviço HTTP local e o endereço do HYDRA-UMC-TELEMETRY-COLLECTOR a que a ponte pode comunicar (no máximo um relatório por segundo)'}]]}, 'troubleshooting': [[{'en': '"bootloaders accept updates signed with the DEVELOPMENT seed, which is public"', 'es': '«los cargadores aceptan actualizaciones firmadas con la semilla de DESARROLLO, que es pública»', 'de': '„Bootloader akzeptieren mit dem ENTWICKLUNGS-Seed signierte Updates, der öffentlich ist“', 'fr': '« les chargeurs acceptent des mises à jour signées avec la graine de DÉVELOPPEMENT, qui est publique »', 'it': '«i bootloader accettano aggiornamenti firmati con il seme di SVILUPPO, che è pubblico»', 'ja': '「ブートローダーは公開されている開発用シードで署名された更新を受け入れます」', 'zh': '“引导程序接受用公开的开发种子签名的更新”', 'pt': '«os carregadores aceitam atualizações assinadas com a semente de DESENVOLVIMENTO, que é pública»'}, {'en': 'The build had no `HYDRA_FW_UPDATE_PUBKEY_HEX` (or no `HYDRA_FW_HMAC_KEY_HEX`)', 'es': 'La compilación no tenía `HYDRA_FW_UPDATE_PUBKEY_HEX` (o no tenía `HYDRA_FW_HMAC_KEY_HEX`)', 'de': 'Der Build hatte kein `HYDRA_FW_UPDATE_PUBKEY_HEX` (oder kein `HYDRA_FW_HMAC_KEY_HEX`)', 'fr': "La compilation n'avait pas `HYDRA_FW_UPDATE_PUBKEY_HEX` (ou pas `HYDRA_FW_HMAC_KEY_HEX`)", 'it': 'La compilazione non aveva `HYDRA_FW_UPDATE_PUBKEY_HEX` (o non aveva `HYDRA_FW_HMAC_KEY_HEX`)', 'ja': 'ビルドに `HYDRA_FW_UPDATE_PUBKEY_HEX`（または `HYDRA_FW_HMAC_KEY_HEX`）がなかった', 'zh': '构建时没有 `HYDRA_FW_UPDATE_PUBKEY_HEX`（或没有 `HYDRA_FW_HMAC_KEY_HEX`）', 'pt': 'A compilação não tinha `HYDRA_FW_UPDATE_PUBKEY_HEX` (ou não tinha `HYDRA_FW_HMAC_KEY_HEX`)'}, {'en': 'Fine for a bench; for any board that someone else can reach, make a key pair with `python tools/image_header.py keygen`, build with the public key and build releases with `HYDRA_UMC_RELEASE=1`', 'es': 'Vale para un banco de pruebas; para cualquier placa que otra persona pueda alcanzar, crea un par de claves con `python tools/image_header.py keygen`, compila con la clave pública y compila las versiones con `HYDRA_UMC_RELEASE=1`', 'de': 'In Ordnung für den Prüfstand; für jede Platine, die jemand anderes erreichen kann, erzeuge ein Schlüsselpaar mit `python tools/image_header.py keygen`, baue mit dem öffentlichen Schlüssel und baue Releases mit `HYDRA_UMC_RELEASE=1`', 'fr': "Acceptable sur un banc ; pour toute carte qu'un tiers peut atteindre, créez une paire de clés avec `python tools/image_header.py keygen`, compilez avec la clé publique et compilez les versions avec `HYDRA_UMC_RELEASE=1`", 'it': 'Va bene per un banco di prova; per qualsiasi scheda raggiungibile da altri, crea una coppia di chiavi con `python tools/image_header.py keygen`, compila con la chiave pubblica e compila le release con `HYDRA_UMC_RELEASE=1`', 'ja': '作業台なら問題ありません。他人が触れる基板には、`python tools/image_header.py keygen` で鍵ペアを作り、公開鍵でビルドし、リリースは `HYDRA_UMC_RELEASE=1` でビルドします', 'zh': '在工作台上没问题；对任何别人可能接触到的电路板，请用 `python tools/image_header.py keygen` 生成密钥对，用公钥构建，并用 `HYDRA_UMC_RELEASE=1` 构建发布版', 'pt': 'Serve numa bancada; para qualquer placa que outra pessoa possa alcançar, crie um par de chaves com `python tools/image_header.py keygen`, compile com a chave pública e compile as versões com `HYDRA_UMC_RELEASE=1`'}], [{'en': '"arm-none-eabi-gcc not found"', 'es': '«arm-none-eabi-gcc no encontrado»', 'de': '„arm-none-eabi-gcc nicht gefunden“', 'fr': '« arm-none-eabi-gcc introuvable »', 'it': '«arm-none-eabi-gcc non trovato»', 'ja': '「arm-none-eabi-gcc が見つかりません」', 'zh': '“未找到 arm-none-eabi-gcc”', 'pt': '«arm-none-eabi-gcc não encontrado»'}, {'en': 'The Arm GNU Toolchain is not installed or not on `PATH`', 'es': 'La cadena de herramientas Arm GNU no está instalada o no está en `PATH`', 'de': 'Die Arm-GNU-Toolchain ist nicht installiert oder nicht im `PATH`', 'fr': "La chaîne d'outils Arm GNU n'est pas installée ou n'est pas dans le `PATH`", 'it': 'La toolchain Arm GNU non è installata o non è nel `PATH`', 'ja': 'Arm GNU ツールチェーンがインストールされていないか、`PATH` にありません', 'zh': '未安装 Arm GNU 工具链，或它不在 `PATH` 中', 'pt': 'A cadeia de ferramentas Arm GNU não está instalada ou não está no `PATH`'}, {'en': 'Install it (the script tries `apt` on Linux) and run the build again; the host tests of step 1b need only a plain C compiler', 'es': 'Instálala (el script prueba `apt` en Linux) y vuelve a compilar; las pruebas de host del paso 1b solo necesitan un compilador de C normal', 'de': 'Installiere sie (das Skript versucht unter Linux `apt`) und baue erneut; die Host-Tests von Schritt 1b brauchen nur einen gewöhnlichen C-Compiler', 'fr': "Installez-la (le script essaie `apt` sous Linux) et relancez la compilation ; les tests hôte de l'étape 1b n'ont besoin que d'un compilateur C ordinaire", 'it': 'Installala (lo script prova `apt` su Linux) e ricompila; i test host del passo 1b richiedono solo un normale compilatore C', 'ja': 'インストールして（スクリプトは Linux で `apt` を試します）再ビルドします。ステップ 1b のホストテストに必要なのは通常の C コンパイラーだけです', 'zh': '安装它（脚本在 Linux 上会尝试 `apt`）并重新构建；1b 步骤的主机测试只需要普通的 C 编译器', 'pt': 'Instale-a (o script tenta `apt` no Linux) e compile de novo; os testes de anfitrião do passo 1b só precisam de um compilador de C normal'}], [{'en': 'The SPI bridge fails to open the device, or `SPI transfer returned ... bytes`', 'es': 'El puente SPI no abre el dispositivo, o `SPI transfer returned ... bytes`', 'de': 'Die SPI-Brücke kann das Gerät nicht öffnen, oder `SPI transfer returned ... bytes`', 'fr': "Le pont SPI n'ouvre pas le périphérique, ou `SPI transfer returned ... bytes`", 'it': 'Il bridge SPI non apre il dispositivo, oppure `SPI transfer returned ... bytes`', 'ja': 'SPI ブリッジがデバイスを開けない、または `SPI transfer returned ... bytes`', 'zh': 'SPI 桥无法打开设备，或出现 `SPI transfer returned ... bytes`', 'pt': 'A ponte SPI não abre o dispositivo, ou `SPI transfer returned ... bytes`'}, {'en': 'The real transport needs `spidev` and `gpiod` on a CM5 with the SPI device enabled, and an STM32H745 on the other end; neither exists yet, so the bridge was only exercised against fakes', 'es': 'El transporte real necesita `spidev` y `gpiod` en una CM5 con el dispositivo SPI activado, y un STM32H745 al otro lado; ninguno existe aún, así que el puente solo se ha ejercitado con simulaciones', 'de': 'Der echte Transport braucht `spidev` und `gpiod` auf einer CM5 mit aktiviertem SPI-Gerät und einen STM32H745 am anderen Ende; beides gibt es noch nicht, die Brücke wurde also nur gegen Attrappen geübt', 'fr': "Le vrai transport demande `spidev` et `gpiod` sur une CM5 dont le périphérique SPI est activé, et un STM32H745 de l'autre côté ; ni l'un ni l'autre n'existe encore, le pont n'a donc été exercé que contre des simulations", 'it': "Il trasporto reale richiede `spidev` e `gpiod` su una CM5 con il dispositivo SPI abilitato, e un STM32H745 dall'altra parte; nessuno dei due esiste ancora, quindi il bridge è stato provato solo con simulazioni", 'ja': '実際のトランスポートには、SPI デバイスを有効にした CM5 上の `spidev` と `gpiod`、反対側の STM32H745 が必要です。どちらもまだ存在しないため、ブリッジは模擬相手でしか試していません', 'zh': '真实传输需要在启用 SPI 设备的 CM5 上有 `spidev` 和 `gpiod`，另一端还要有 STM32H745；两者目前都不存在，因此桥只对模拟对象试过', 'pt': 'O transporte real precisa de `spidev` e `gpiod` numa CM5 com o dispositivo SPI ativado, e de um STM32H745 do outro lado; nenhum existe ainda, por isso a ponte só foi exercitada com simulações'}, {'en': 'Use the fake transport of the tests until a board exists', 'es': 'Usa el transporte simulado de las pruebas hasta que exista una placa', 'de': 'Nutze bis zum Vorhandensein einer Platine den Attrappen-Transport der Tests', 'fr': "Utilisez le transport simulé des tests tant qu'aucune carte n'existe", 'it': 'Usa il trasporto simulato dei test finché non esiste una scheda', 'ja': '基板ができるまでは、テストの模擬トランスポートを使う', 'zh': '在有电路板之前，使用测试中的模拟传输', 'pt': 'Use o transporte simulado dos testes até existir uma placa'}], [{'en': '`build_firmware.sh` ends with FAIL at a host test', 'es': '`build_firmware.sh` termina con FAIL en una prueba de host', 'de': '`build_firmware.sh` endet mit FAIL bei einem Host-Test', 'fr': '`build_firmware.sh` se termine par FAIL sur un test hôte', 'it': '`build_firmware.sh` termina con FAIL in un test host', 'ja': '`build_firmware.sh` がホストテストで FAIL で終わる', 'zh': '`build_firmware.sh` 在某个主机测试处以 FAIL 结束', 'pt': '`build_firmware.sh` termina com FAIL num teste de anfitrião'}, {'en': 'The copies of a source that the three bootloaders share have drifted apart, or `tests/image_header_vectors.h` is older than `tools/image_header.py`', 'es': 'Las copias de una fuente que comparten los tres cargadores se han separado, o `tests/image_header_vectors.h` es más viejo que `tools/image_header.py`', 'de': 'Die Kopien einer Quelle, die die drei Bootloader teilen, sind auseinandergelaufen, oder `tests/image_header_vectors.h` ist älter als `tools/image_header.py`', 'fr': "Les copies d'une source que partagent les trois chargeurs ont divergé, ou `tests/image_header_vectors.h` est plus ancien que `tools/image_header.py`", 'it': 'Le copie di un sorgente condiviso dai tre bootloader sono divergenti, oppure `tests/image_header_vectors.h` è più vecchio di `tools/image_header.py`', 'ja': '3 つのブートローダーが共有するソースのコピーがずれたか、`tests/image_header_vectors.h` が `tools/image_header.py` より古い', 'zh': '三个引导程序共用的某个源文件的副本已出现差异，或 `tests/image_header_vectors.h` 比 `tools/image_header.py` 旧', 'pt': 'As cópias de uma fonte que os três carregadores partilham afastaram-se, ou `tests/image_header_vectors.h` é mais antigo do que `tools/image_header.py`'}, {'en': 'Run `python tools/gen_image_header_vectors.py` and `python -m unittest discover -s tests` to see which copy differs', 'es': 'Ejecuta `python tools/gen_image_header_vectors.py` y `python -m unittest discover -s tests` para ver qué copia difiere', 'de': 'Führe `python tools/gen_image_header_vectors.py` und `python -m unittest discover -s tests` aus, um zu sehen, welche Kopie abweicht', 'fr': 'Lancez `python tools/gen_image_header_vectors.py` et `python -m unittest discover -s tests` pour voir quelle copie diffère', 'it': 'Esegui `python tools/gen_image_header_vectors.py` e `python -m unittest discover -s tests` per vedere quale copia differisce', 'ja': '`python tools/gen_image_header_vectors.py` と `python -m unittest discover -s tests` を実行して、どのコピーが違うかを確認する', 'zh': '运行 `python tools/gen_image_header_vectors.py` 和 `python -m unittest discover -s tests`，看看是哪份副本不同', 'pt': 'Execute `python tools/gen_image_header_vectors.py` e `python -m unittest discover -s tests` para ver que cópia difere'}]], 'roadmap': {'en': 'What exists today is limited to the three bootloaders, the CM4 and G474 communication applications and the CM5-side SPI bridge; the rest of the specification is design. No custom board has been populated or tested, the two board folders hold no schematic yet, and the applications are FreeRTOS smoke tests that toggle a pin, not the motion, vision and relay firmware. The bootloaders and the bridge were tested on a host computer, never on the real chips.', 'es': 'Lo que existe hoy se limita a los tres cargadores de arranque, las aplicaciones de comunicación de la CM4 y la G474 y el puente SPI del lado de la CM5; el resto de la especificación es diseño. No se ha montado ni probado ninguna placa propia, las dos carpetas de placa aún no tienen esquema, y las aplicaciones son pruebas de humo de FreeRTOS que conmutan un pin, no el firmware de movimiento, visión y relé. Los cargadores y el puente se probaron en un ordenador anfitrión, nunca en los chips reales.', 'de': 'Was es heute gibt, beschränkt sich auf die drei Bootloader, die Kommunikationsanwendungen von CM4 und G474 und die SPI-Brücke auf der CM5-Seite; der Rest der Spezifikation ist Entwurf. Keine eigene Platine wurde bestückt oder getestet, die beiden Platinenordner enthalten noch keinen Schaltplan, und die Anwendungen sind FreeRTOS-Rauchtests, die einen Pin schalten, nicht die Bewegungs-, Vision- und Relay-Firmware. Bootloader und Brücke wurden auf einem Host-Rechner getestet, nie auf den echten Chips.', 'fr': "Ce qui existe aujourd'hui se limite aux trois chargeurs d'amorçage, aux applications de communication CM4 et G474 et au pont SPI côté CM5 ; le reste de la spécification est de la conception. Aucune carte propre n'a été assemblée ni testée, les deux dossiers de carte ne contiennent pas encore de schéma, et les applications sont des tests de fumée FreeRTOS qui basculent une broche, pas le firmware de mouvement, de vision et de relais. Les chargeurs et le pont ont été testés sur un ordinateur hôte, jamais sur les vraies puces.", 'it': 'Ciò che esiste oggi si limita ai tre bootloader, alle applicazioni di comunicazione di CM4 e G474 e al bridge SPI lato CM5; il resto della specifica è progetto. Nessuna scheda propria è stata assemblata o provata, le due cartelle di scheda non contengono ancora uno schema, e le applicazioni sono smoke test FreeRTOS che commutano un pin, non il firmware di movimento, visione e relay. Bootloader e bridge sono stati provati su un computer host, mai sui chip reali.', 'ja': '現時点で存在するのは、3 つのブートローダー、CM4 と G474 の通信アプリケーション、CM5 側の SPI ブリッジだけで、仕様の残りは設計です。独自基板は実装も試験もされておらず、2 つの基板フォルダーにはまだ回路図がなく、アプリケーションは動作・ビジョン・リレーのファームウェアではなく、ピンを切り替えるだけの FreeRTOS スモークテストです。ブートローダーとブリッジはホストコンピューターで試験し、実チップでは一度も試していません。', 'zh': '目前已有的仅限于三个引导程序、CM4 和 G474 的通信应用以及 CM5 一侧的 SPI 桥；规格的其余部分都是设计。尚未装配或测试任何自制电路板，两个电路板文件夹还没有原理图，应用是只切换一个引脚的 FreeRTOS 冒烟测试，而不是运动、视觉和中继固件。引导程序和桥只在主机上测试过，从未在真实芯片上测试。', 'pt': 'O que existe hoje limita-se aos três carregadores de arranque, às aplicações de comunicação da CM4 e da G474 e à ponte SPI do lado da CM5; o resto da especificação é desenho. Nenhuma placa própria foi montada ou testada, as duas pastas de placa ainda não têm esquema, e as aplicações são testes de fumo FreeRTOS que comutam um pino, não o firmware de movimento, visão e relé. Os carregadores e a ponte foram testados num computador anfitrião, nunca nos chips reais.'}}


def EXTRA(lg):
    out = {}
    sec = EXTRAS.get("security")
    if sec:
        out["security"] = K.table(lg, "threat", sec["rows"]) + ("\n\n" + K.pick(sec["never"], lg) if sec.get("never") else "")
    cfg = EXTRAS.get("configuration")
    if cfg:
        out["configuration"] = (K.pick(cfg["intro"], lg) + "\n\n" if cfg.get("intro") else "") + K.table(lg, "config", cfg["rows"])
    trb = EXTRAS.get("troubleshooting")
    if trb:
        out["troubleshooting"] = K.table(lg, "trouble", trb)
    be = EXTRAS.get("build_extra")
    if be:
        out["_build_extra"] = K.pick(be, lg)
    ov = EXTRAS.get("overview")
    if ov:
        out["overview"] = K.pick(ov, lg)
    rdm = EXTRAS.get("roadmap")
    if rdm:
        out["roadmap"] = K.pick(rdm, lg)
    itf = EXTRAS.get("interfaces")
    if itf:
        out["interfaces"] = K.table(lg, itf["head"], itf["rows"]) if isinstance(itf["head"], str) else K.table(lg, [K.pick(h, lg) for h in itf["head"]], itf["rows"])
    return out


def DOCS(lg, ctx):
    return [f"[{path}]({path}) - {text[lg]}" for path, text in DOCS_EXTRA] + S.docs_items(lg, ctx)


def BODY(lg, ctx):
    body = S.make_body(lg, ctx, SPEC)
    for key, src in APPEND.items():
        if ctx.has(lg, src):
            body[key] = body[key] + "\n\n" + ctx.v(lg, src)
    if ctx.has(lg, "features"):
        body["features"] = ctx.v(lg, "features")
    extra = EXTRA(lg)
    if ctx.has(lg, "structure_note"):
        body["structure"] = ctx.v(lg, "structure_note")
    for key in ("interfaces", "configuration", "troubleshooting", "security"):
        if ctx.has(lg, key):
            extra[key] = ctx.v(lg, key) + (("\n\n" + extra[key]) if key in extra else "")
    be = extra.pop("_build_extra", None)
    if be:
        body["build"] = body.get("build", "") + "\n\n" + be
    body.update(extra)
    return body
